          //board switches to 3V3, the ADC_REF should be 3.3\n#define GROVE_VCC 5 //VCC of the grove interface is normally 5v\n#define FULL_ANGLE 300 //full value of the rotary angle is 300 degrees\n\nvoid setup()\n{\n    Serial.begin(9600);\n    pinMode(ROTARY_ANGLE_SENSOR, INPUT);\n    pinMode(LED,OUTPUT);   \n}\n\nvoid loop()\n{   \n    float voltage;\n    int sensor_value = analogRead(ROTARY_ANGLE_SENSOR);\n    voltage = (float)sensor_value*ADC_REF/1023;\n    float degrees = (voltage*FULL_ANGLE)/GROVE_VCC;\n    Serial.println("The angle between the mark and the starting position:");\n    Serial.println(degrees);\n\n    int brightness;\n    brightness = map(degrees, 0, FULL_ANGLE, 0, 255);\n    analogWrite(LED,brightness);\n    delay(500);\n}\n\n'})}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"\u6B65\u9AA42."})," \u8C03\u6574Grove-\u65CB\u8F6C\u89D2\u5EA6\u4F20\u611F\u5668\uFF0C\u6211\u4EEC\u5C06\u770B\u5230Grove-LED\u6539\u53D8\u4EAE\u5EA6\u3002"]}),"\n"]}),"\n",(0,i.jsx)(n.h3,{id:"\u4E0Ecodecraft\u4E00\u8D77\u4F7F\u7528",children:"\u4E0ECodecraft\u4E00\u8D77\u4F7F\u7528"}),"\n",(0,i.jsx)(n.h4,{id:"\u786C\u4EF6",children:"\u786C\u4EF6"}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"\u6B65\u9AA41."})," \u5C06Grove - \u65CB\u8F6C\u89D2\u5EA6\u4F20\u611F\u5668\u8FDE\u63A5\u5230Base Shield\u7684A0\u7AEF\u53E3\uFF0C\u5E76\u5C06Grove - \u7EA2\u8272LED\u8FDE\u63A5\u5230D3\u7AEF\u53E3\u3002"]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"\u6B65\u9AA42."})," \u5C06Base Shield\u63D2\u5165\u60A8\u7684Seeeduino/Arduino\u3002"]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"\u6B65\u9AA43."})," \u901A\u8FC7USB\u7EBF\u5C06Seeeduino/Arduino\u8FDE\u63A5\u5230\u60A8\u7684PC\u3002"]}),"\n",(0,i.jsx)(n.h4,{id:"\u8F6F\u4EF6",children:"\u8F6F\u4EF6"}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"\u6B65\u9AA41."})," \u6253\u5F00",(0,i.jsx)(n.a,{href:"https://ide.chmakere